PAYLOAD=''
SOURCE_HASH='5758ca719357f2ee201ae1081dc2c8a90795cffeb45554be569d93e98e3fff98'
CORE='0fd7b3e32217bc9d9ab6659e72f5925a7d179751'
WORKER='2bfde0d6b4743227900a33d0d140990788425d34'
RECIPES=('ticket-sorter-hinglish', 'invoice-fields', 'product-descriptions', 'faq-bot-hinglish', 'review-sentiment')
import base64,csv,gc,hashlib,io,json,shutil,subprocess,sys,tarfile,time,traceback
from pathlib import Path
subprocess.run([sys.executable,'-m','pip','uninstall','-y','torchao'],check=True)
subprocess.run([sys.executable,'-m','pip','install','pyrage>=1.4,<2'],check=True)
import torch
if not torch.cuda.is_available():raise RuntimeError('CUDA GPU required')
gpu=torch.cuda.get_device_name(0)
print('GPU',gpu,flush=True)
if 'T4' not in gpu:raise RuntimeError('this run is intended for T4, got '+gpu)
raw=base64.b64decode(PAYLOAD)
if hashlib.sha256(raw).hexdigest()!=SOURCE_HASH:raise RuntimeError('source hash mismatch')
root=Path('/kaggle/temp/cost-matrix-src');root.mkdir(parents=True,exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz') as outer:
    for member in outer.getmembers():
        with tarfile.open(fileobj=io.BytesIO(outer.extractfile(member).read()),mode='r:') as inner:
            inner.extractall(root,filter='data')
sys.path[:0]=[str(root/'packages/ekido_core'),str(root/'runtime')]
from ekido_core.job_spec import MODEL_REVISIONS
from ekido_runtime.distill import build_student_spec
from ekido_runtime.train import write_dataset,run_training
out=Path('/kaggle/working/cost-matrix');out.mkdir(parents=True,exist_ok=True)
recipes=RECIPES
config={'micro_batch':1,'accumulation':8,'amp':'fp16','grad_checkpointing':True,'attention_impl':'sdpa','loader_workers':0}
summary={'core_commit':CORE,'worker_commit':WORKER,'gpu':gpu,'steps':20,'config':config,
         'scope':'20-step short training-loop measurement; checkpoint IO included, loading and evaluation excluded',
         'prices':'No hourly GPU tariff supplied; no cost estimate is claimed.','runs':{}}
for name in recipes:
    folder=root/'experiments/recipes'/name
    def read(filename):
        with (folder/filename).open(encoding='utf-8',newline='') as f:return list(csv.DictReader(f))
    training,test=read('train.csv'),read('test.csv')
    for model,revision in MODEL_REVISIONS.items():
        alias=model.rsplit('/',1)[-1].lower();key=name+'-'+alias
        target=out/key;target.mkdir(exist_ok=True)
        print('START',key,flush=True)
        try:
            dataset=target/'dataset.jsonl';digest,nbytes=write_dataset(dataset,training,test)
            spec=build_student_spec(name,student_model=model,student_revision=revision,digest=digest,nbytes=nbytes,
                                    train_rows=len(training),test_rows=len(test),steps=20)
            (target/'spec.json').write_text(json.dumps(spec,indent=2),encoding='utf-8')
            result=run_training(spec,dataset,target/'training',device='cuda',exec_config=config,measure_training=True)
            metrics=result['training_metrics']
            if metrics['steps']!=20 or metrics['non_padding_tokens']<=0 or metrics['seconds']<=0:
                raise RuntimeError('invalid measurement')
            data={'status':'complete','recipe':name,'model':model,'model_revision':revision,'gpu':gpu,
                  'core_commit':CORE,'worker_commit':WORKER,'dataset_sha256':digest,
                  'train_rows':len(training),'test_rows':len(test),'measurement':metrics,
                  'note':'Short T4 training segment; no tariff or per-million monetary cost was supplied.'}
            (out/(key+'.json')).write_text(json.dumps(data,indent=2),encoding='utf-8')
            summary['runs'][key]={'status':'complete','file':key+'.json',**metrics}
            # Costs, not model delivery: keep manifest, but avoid exporting 10 optimizer/checkpoint copies.
            checkpoint=target/'training/checkpoints/step-20'
            if (checkpoint/'manifest.json').is_file():shutil.copyfile(checkpoint/'manifest.json',target/'checkpoint-manifest.json')
            shutil.rmtree(target/'training/checkpoints',ignore_errors=True)
        except Exception as exc:
            summary['runs'][key]={'status':'error','error':str(exc)[:500]}
            traceback.print_exc()
        finally:
            (out/'summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
            gc.collect();torch.cuda.empty_cache()
        print('FINISH',key,summary['runs'][key]['status'],flush=True)
if len(summary['runs'])!=10 or any(v['status']!='complete' for v in summary['runs'].values()):
    raise RuntimeError('One or more matrix entries failed')
